import XCTest
@testable import TelemetryCore

// NOT RUN: Swift execution intentionally deferred. Same 70 synthetic cases as Python (67 fixtures + 3 boundary tests).
final class Mode01BatchProposalTests: XCTestCase {
    private struct Case: Decodable {
        let name: String
        let input: Mode01BatchProposal.Input
        let record: Mode01BatchProposal.Record?
        let expected: String
    }
    private func run(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let cases = try JSONDecoder().decode([Case].self, from: Data(Self.fixtures.utf8))
        let test = try XCTUnwrap(cases.first { $0.name == name }, file: file, line: line)
        let result = Mode01BatchProposal.evaluate(test.input, record: test.record)
        XCTAssertEqual(result.reason, test.expected, file: file, line: line)
        XCTAssertEqual(result.record, test.record, file: file, line: line)
        XCTAssertEqual(result.input, test.input, file: file, line: line)
        if test.record != nil {
            if test.expected == "ok" {
                XCTAssertEqual(result.values?.map { $0.pid }, [12, 13], file: file, line: line)
                let expected: [[UInt8]] = name == "real_zero_bytes" ? [[0, 0], [0]] : [[1, 2], [3]]
                XCTAssertEqual(result.values?.map { $0.bytes }, expected, file: file, line: line)
                XCTAssertNil(result.fallback, file: file, line: line)
            } else {
                XCTAssertNil(result.values, file: file, line: line)
                XCTAssertEqual(result.fallback, [[1, 12], [1, 13]], file: file, line: line)
            }
        }
        if test.expected == "ok" {
            XCTAssertEqual(result.plan?.request, [1, 12, 13], file: file, line: line)
            XCTAssertEqual(result.plan?.evidence, test.input, file: file, line: line)
        } else if test.record == nil {
            XCTAssertNil(result.plan, file: file, line: line)
            XCTAssertNil(result.fallback, file: file, line: line)
        }
    }
    private func boundaryInput(count: Int, length: Int = 32, protocolName: String = "iso15765-4-can11-500") -> Mode01BatchProposal.Input {
        let c = Mode01BatchProposal.Context(request: 0x7E0, response: 0x7E8,
            protocol: protocolName, session: "session-A", generation: 3, adapter: "adapter-A")
        let items = (1...count).map { Mode01BatchProposal.Item(pid: $0, length: length,
            context: c, supportEvidence: "synthetic-support", lengthEvidence: "synthetic-length", proven: true) }
        return Mode01BatchProposal.Input(enabled: true, context: c, items: items,
            adapterContext: c, adapterBatchCapable: true, adapterEvidence: "synthetic-adapter-proof",
            correlation: "request-A", variant: Mode01BatchProposal.applicationVariant)
    }
    func test_maximum_six_pids_199_bytes() {
        let input = boundaryInput(count: 6)
        let payload: [UInt8] = [65] + (1...6).flatMap { [UInt8($0)] + Array(repeating: UInt8(65), count: 32) }
        let record = Mode01BatchProposal.Record(context: input.context, correlation: "request-A",
            variant: Mode01BatchProposal.applicationVariant, status: "complete", payload: payload,
            sourceEvidence: "synthetic-record", rawEvidence: "synthetic retained source")
        let outcome = Mode01BatchProposal.evaluate(input, record: record)
        XCTAssertEqual(outcome.reason, "ok")
        XCTAssertEqual(outcome.plan?.request, [1,1,2,3,4,5,6])
        XCTAssertEqual(outcome.values?.map { $0.pid }, [1,2,3,4,5,6])
        XCTAssertEqual(outcome.values?.map { $0.bytes }, Array(repeating: Array(repeating: UInt8(65), count: 32), count: 6))
    }
    func test_seven_distinct_pids() {
        XCTAssertEqual(Mode01BatchProposal.evaluate(boundaryInput(count: 7)).reason, "item_count")
    }
    func test_can250_explicitly_matched() {
        XCTAssertEqual(Mode01BatchProposal.evaluate(boundaryInput(count: 2, length: 2,
            protocolName: "iso15765-4-can11-250")).reason, "ok")
    }
